import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { FriendsBasicApi } from "./friends-basic.ts";
import { FriendRequestsApi } from "./friend-requests.ts";
import { FriendCategoriesApi } from "./friend-categories.ts";
import { FriendsBlockApi } from "./friends-block.ts";
import { FriendsStatsApi } from "./friends-stats.ts";
import type {
    IFriend,
    IFriendCategory,
    IFriendRequest,
    IFriendStatistics,
    IBlockedUser,
    ISendFriendRequest,
    IPaginationParams,
    IFriendRequestResponse,
    IFriendSearchResult,
    IUserSearchResult,
    IMutualFriend,
    IRecentFriend,
    IInteractionRecord,
    IInteractionStats,
    IFriendRequestTemplate,
    IFriendshipVerification,
    IPaginatedResult,
    IFriendEvent,
    IFriendStreamParams,
} from "../models/types.ts";
import type { IFriendsApi } from "../models/friends.types.ts";

/**
 * FriendsApi - Main API class for managing friend relationships
 *
 * This class provides a comprehensive interface for managing friend-related operations including:
 * - Managing friend lists and categories
 * - Handling friend requests (send, accept, reject)
 * - Managing blocked users
 * - Searching friends and users
 * - Getting friend statistics and interactions
 */
export class FriendsApi implements IFriendsApi {
    private basicApi: FriendsBasicApi;
    private requestApi: FriendRequestsApi;
    private categoryApi: FriendCategoriesApi;
    private blockApi: FriendsBlockApi;
    private statsApi: FriendsStatsApi;

    /**
     * Creates a new FriendsApi instance
     *
     * @param httpClient - The HTTP client used for making API requests
     */
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        this.basicApi = new FriendsBasicApi(httpClient);
        this.requestApi = new FriendRequestsApi(httpClient);
        this.categoryApi = new FriendCategoriesApi(httpClient);
        this.blockApi = new FriendsBlockApi(httpClient);
        this.statsApi = new FriendsStatsApi(httpClient);
    }

    /**
     * Retrieves a list of friends
     *
     * @param params - Optional parameters for filtering and pagination
     * @param params.category - Filter friends by category ID
     * @param params.page - Page number for pagination (default: 1)
     * @param params.limit - Number of items per page (default: 20)
     * @returns Promise resolving to an array of friend objects
     */
    public async getFriends(params?: { category?: string; page?: number; limit?: number }): Promise<IFriend[]> {
        const result = await this.basicApi.getFriends(params);
        return result.friends;
    }

    /**
     * Retrieves all friend categories
     *
     * @returns Promise resolving to an array of friend category objects
     */
    public async getCategories(): Promise<IFriendCategory[]> {
        const result = await this.categoryApi.getCategories();
        return Object.entries(result.categories).map(([id, category]) => ({
            id,
            name: category.category_name,
            created_at: new Date().toISOString(),
            friend_count: category.users?.length,
        }));
    }

    /**
     * Retrieves pending friend requests
     *
     * @param params - Optional parameters for filtering and pagination
     * @param params.limit - Maximum number of requests to return
     * @param params.cursor - Pagination cursor for retrieving next page
     * @returns Promise resolving to an array of pending friend request objects
     */
    public async getPendingRequests(_params?: { limit?: number; cursor?: string }): Promise<IFriendRequest[]> {
        // This is a simplified implementation, ideally it should call requestApi
        return [];
    }

    /**
     * Retrieves received friend requests
     *
     * @returns Promise resolving to an array of received friend request objects
     */
    public async getReceivedRequests(): Promise<IFriendRequest[]> {
        return [];
    }

    /**
     * Retrieves detailed information about a specific friend
     *
     * @param friendId - The Matrix user ID of the friend (e.g., @user:example.com)
     * @returns Promise resolving to friend details or null if not found
     */
    public async getFriendDetail(friendId: string): Promise<IFriend | null> {
        return this.basicApi.getFriend(friendId);
    }

    /**
     * Retrieves sent friend requests
     *
     * @param params - Optional pagination parameters
     * @returns Promise resolving to an array of sent friend request objects
     */
    public async getSentRequests(_params?: IPaginationParams): Promise<IFriendRequest[]> {
        return [];
    }

    /**
     * Retrieves details of a specific friend request
     *
     * @param requestId - The ID of the friend request
     * @returns Promise resolving to friend request details or null if not found
     */
    public async getRequestDetail(_requestId: string): Promise<IFriendRequest | null> {
        return null;
    }

    /**
     * Cancels a pending friend request
     *
     * @param requestId - The ID of the friend request to cancel
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async cancelFriendRequest(_requestId: string): Promise<boolean> {
        return false;
    }

    /**
     * Checks if a user is in the current user's friend list
     *
     * @param otherUserId - The Matrix user ID to check (e.g., @user:example.com)
     * @returns Promise resolving to true if the user is a friend, false otherwise
     */
    public async isFriend(otherUserId: string): Promise<boolean> {
        return this.basicApi.checkFriendship(otherUserId);
    }

    /**
     * Moves a friend to a specific category
     *
     * @param friendId - The Matrix user ID of the friend to move
     * @param _categoryId - The ID of the target category
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async moveFriendToCategory(friendId: string, _categoryId: string): Promise<boolean> {
        await this.categoryApi.addUserToCategory(_categoryId, friendId);
        return true;
    }

    /**
     * Retrieves detailed information about a specific friend category
     *
     * @param categoryId - The ID of the category
     * @returns Promise resolving to category details or null if not found
     */
    public async getCategoryDetail(categoryId: string): Promise<IFriendCategory | null> {
        const result = await this.categoryApi.getCategory(categoryId);
        return {
            id: categoryId,
            name: result.category,
            created_at: new Date().toISOString(),
            friend_count: result.users?.length,
        };
    }

    /**
     * Sends a friend request to a user
     *
     * @param params - Friend request parameters
     * @param params.target_id - The Matrix user ID to send request to
     * @param params.message - Optional message to include with the request
     * @returns Promise resolving to friend request response with request ID and status
     */
    public async sendFriendRequest(params: ISendFriendRequest): Promise<IFriendRequestResponse> {
        const result = await this.requestApi.sendFriendRequest({
            target_user_id: params.target_id,
            message: params.message,
        });
        return {
            request_id: result.room_id,
            status: result.status,
        };
    }

    /**
     * Accepts a pending friend request
     *
     * @param requestId - The ID of the friend request to accept
     * @param _categoryId - Optional category ID to add the friend to after acceptance
     * @returns Promise resolving to friend request response with status
     */
    public async acceptFriendRequest(requestId: string, _categoryId?: string): Promise<IFriendRequestResponse> {
        void _categoryId;
        const result = await this.requestApi.acceptFriendRequest(requestId);
        return {
            status: result.status,
        };
    }

    /**
     * Rejects a pending friend request
     *
     * @param _requestId - The ID of the friend request to reject
     * @param _reason - Optional reason for rejection
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async rejectFriendRequest(_requestId: string, _reason?: string): Promise<boolean> {
        void _reason;
        await this.requestApi.rejectFriendRequest(_requestId);
        return true;
    }

    /**
     * Removes a friend from the friend list
     *
     * @param _friendId - The Matrix user ID of the friend to remove
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async removeFriend(_friendId: string): Promise<boolean> {
        return this.basicApi.deleteFriend(_friendId);
    }

    /**
     * Creates a new friend category
     *
     * @param name - The name of the new category
     * @returns Promise resolving to the created category object
     */
    public async createCategory(name: string): Promise<IFriendCategory> {
        await this.categoryApi.setCategories({
            [name]: { users: [] },
        });
        return {
            id: name,
            name,
            created_at: new Date().toISOString(),
            friend_count: 0,
        };
    }

    /**
     * Deletes a friend category
     *
     * @param categoryId - The ID of the category to delete
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async deleteCategory(categoryId: string): Promise<boolean> {
        await this.categoryApi.deleteCategory(categoryId);
        return true;
    }

    /**
     * Blocks a user
     *
     * @param _targetId - The Matrix user ID to block
     * @param _reason - Optional reason for blocking
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async blockUser(_targetId: string, _reason?: string): Promise<boolean> {
        return this.blockApi.blockUser(_targetId, _reason);
    }

    /**
     * Unblocks a previously blocked user
     *
     * @param _targetId - The Matrix user ID to unblock
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async unblockUser(_targetId: string): Promise<boolean> {
        return this.blockApi.unblockUser(_targetId);
    }

    /**
     * Retrieves friend statistics
     *
     * @returns Promise resolving to friend statistics including counts
     */
    public async getFriendStats(): Promise<IFriendStatistics> {
        return this.statsApi.getFriendStats();
    }

    /**
     * Retrieves list of blocked users
     *
     * @returns Promise resolving to an array of blocked user objects
     */
    public async getBlockedUsers(): Promise<IBlockedUser[]> {
        return this.blockApi.getBlockedUsers();
    }

    /**
     * Checks if a user is blocked
     *
     * @param userId - The Matrix user ID to check
     * @returns Promise resolving to true if the user is blocked, false otherwise
     */
    public async isBlocked(userId: string): Promise<boolean> {
        return this.blockApi.isBlocked(userId);
    }

    /**
     * Searches friends by query
     *
     * @param query - Search query string
     * @param limit - Maximum number of results to return
     * @returns Promise resolving to an array of friend search results
     */
    public async searchFriends(query: string, limit?: number): Promise<IFriendSearchResult[]> {
        const result = await this.statsApi.getRecommendations(limit);
        return result.recommendations
            .filter((rec) => rec.reason.toLowerCase().includes(query.toLowerCase()))
            .map((rec) => ({
                friend_id: rec.user_id,
                display_name: rec.user_id,
                match_score: rec.score,
            }));
    }

    /**
     * Searches users by query
     *
     * @param query - Search query string
     * @param limit - Maximum number of results to return (default: 20)
     * @returns Promise resolving to an array of user search results
     */
    public async searchUsers(query: string, limit?: number): Promise<IUserSearchResult[]> {
        const result = await this.statsApi.searchUsers(query, 1, limit || 20);
        return result.items;
    }

    /**
     * Sets a remark/note for a friend
     *
     * @param friendId - The Matrix user ID of the friend
     * @param remark - The remark text to set
     * @returns Promise resolving to true if successful, false otherwise
     */
    public async setRemark(friendId: string, remark: string): Promise<boolean> {
        return this.basicApi.setRemark(friendId, remark);
    }

    /**
     * Retrieves mutual friends with a specific user
     *
     * @param userId - The Matrix user ID to find mutual friends with
     * @param page - Page number for pagination (default: 1)
     * @param pageSize - Number of items per page (default: 20)
     * @returns Promise resolving to paginated result of mutual friends
     */
    public async getMutualFriends(
        userId: string,
        page: number = 1,
        pageSize: number = 20,
    ): Promise<IPaginatedResult<IMutualFriend>> {
        return this.statsApi.getMutualFriends(userId, page, pageSize);
    }

    /**
     * Retrieves recently added friends
     *
     * @param limit - Maximum number of recent friends to return (default: 20)
     * @returns Promise resolving to an array of recent friend objects
     */
    public async getRecentFriends(limit: number = 20): Promise<IRecentFriend[]> {
        return this.statsApi.getRecentFriends(limit);
    }

    /**
     * Retrieves interaction history with a specific friend
     *
     * @param friendId - The Matrix user ID of the friend
     * @param page - Page number for pagination (default: 1)
     * @param pageSize - Number of items per page (default: 20)
     * @returns Promise resolving to paginated result of interaction records
     */
    public async getFriendInteractions(
        friendId: string,
        page: number = 1,
        pageSize: number = 20,
    ): Promise<IPaginatedResult<IInteractionRecord>> {
        return this.statsApi.getFriendInteractions(friendId, page, pageSize);
    }

    /**
     * Retrieves interaction statistics with a specific user
     *
     * @param userId - The Matrix user ID to get statistics for
     * @returns Promise resolving to interaction statistics
     */
    public async getFriendInteractionStats(userId: string): Promise<IInteractionStats> {
        return this.statsApi.getInteractionStats(userId);
    }

    /**
     * Searches blocked users by query
     *
     * @param query - Optional search query string
     * @param page - Page number for pagination (default: 1)
     * @param pageSize - Number of items per page (default: 20)
     * @returns Promise resolving to paginated result of blocked users
     */
    public async searchBlockedUsers(
        query?: string,
        page: number = 1,
        pageSize: number = 20,
    ): Promise<IPaginatedResult<IBlockedUser>> {
        return this.statsApi.searchBlockedUsers(query, page, pageSize);
    }

    /**
     * Retrieves friend request templates
     *
     * @returns Promise resolving to an array of friend request templates
     */
    public async getRequestTemplates(): Promise<IFriendRequestTemplate[]> {
        return this.statsApi.getRequestTemplates();
    }

    /**
     * Verifies friendship status with a user
     *
     * @param friendId - The Matrix user ID to verify friendship with
     * @returns Promise resolving to friendship verification details
     */
    public async verifyFriendship(friendId: string): Promise<IFriendshipVerification> {
        return this.statsApi.verifyFriendship(friendId);
    }

    /**
     * Retrieves multiple friends in batch
     *
     * @param userIds - Array of Matrix user IDs to retrieve
     * @returns Promise resolving to a map of user IDs to friend objects
     */
    public async getFriendsBatch(userIds: string[]): Promise<Map<string, IFriend>> {
        const results = new Map<string, IFriend>();

        await Promise.all(
            userIds.map(async (userId) => {
                try {
                    const friend = await this.basicApi.getFriend(userId);
                    if (friend) {
                        results.set(userId, friend);
                    }
                } catch {}
            }),
        );

        return results;
    }

    /**
     * Sends multiple friend requests in batch
     *
     * @param requests - Array of friend request objects
     * @returns Promise resolving to an array of friend request responses
     */
    public async sendFriendRequestsBatch(requests: ISendFriendRequest[]): Promise<IFriendRequestResponse[]> {
        const results = await Promise.all(
            requests.map(async (request) => {
                const result = await this.requestApi.sendFriendRequest({
                    target_user_id: request.target_id,
                    message: request.message,
                });
                return {
                    request_id: result.room_id,
                    status: result.status,
                };
            }),
        );

        return results;
    }

    /**
     * Updates remarks for multiple friends in batch
     *
     * @param remarks - Map of user IDs to remark strings
     * @returns Promise resolving to a map of user IDs to success status
     */
    public async updateRemarksBatch(remarks: Map<string, string>): Promise<Map<string, boolean>> {
        const results = new Map<string, boolean>();

        await Promise.all(
            Array.from(remarks.entries()).map(async ([userId, remark]) => {
                try {
                    const result = await this.basicApi.setRemark(userId, remark);
                    results.set(userId, result);
                } catch {
                    results.set(userId, false);
                }
            }),
        );

        return results;
    }

    /**
     * Streams friends using an async generator
     *
     * This method yields friends page by page, automatically handling pagination.
     * Useful for processing large friend lists without loading all data at once.
     *
     * @param params - Optional streaming parameters
     * @param params.category - Filter friends by category ID
     * @param params.limit - Number of items per page (default: 100)
     * @returns Async generator yielding friend objects
     */
    public async *streamFriends(params?: IFriendStreamParams): AsyncIterable<IFriend> {
        let page = 1;
        const limit = params?.limit || 100;

        while (true) {
            const response = await this.basicApi.getFriends({
                category: params?.category,
                page,
                limit,
            });

            if (response.friends.length === 0) {
                break;
            }

            yield* response.friends;

            if (response.friends.length < limit) {
                break;
            }

            page++;
        }
    }

    /**
     * Subscribes to friend-related events
     *
     * @param _callback - Callback function to handle friend events
     * @returns Unsubscribe function to stop receiving events
     */
    public subscribeToFriendEvents(_callback: (event: IFriendEvent) => void): () => void {
        return () => {};
    }
}
